// Applies the current resize-derived font scale to labels set from .trs files,
// so language changes do not reset text scaling.
extern int carcalc_scaled_font_size(int size);
// Recomputes label rows after a language change changes .trs font sizes.
extern void carcalc_relayout();
// Fuel usage is read only from the selected database. The schema has no
// urban/exurban columns, so the exact mixed figure is averaged from
// conso_mixte_min/max by the data layer.
static void refresh_fuel_usage()
{
	if (!lbl_fuel_usage) return;
	const int brand_row = lst_car_models ? lst_car_models->value() : 0;
	const int model_row = lst_car_engines ? lst_car_engines->value() : 0;
	if (brand_row <= 0 || model_row <= 0)
	{
		lbl_fuel_usage->value("");
		return;
	}

	const char* brand = lst_car_models->text(brand_row);
	const char* model = lst_car_engines->text(model_row);
	if (!brand || !model)
	{
		lbl_fuel_usage->value("");
		return;
	}

	std::string gearbox;
	if (lst_car_gearboxes && lst_car_gearboxes->value() > 0)
	{
		const char* text = lst_car_gearboxes->text(lst_car_gearboxes->value());
		if (text) gearbox = text;
	}
	std::string energy;
	if (cbo_fuel_selectcar && cbo_fuel_selectcar->value() >= 0)
	{
		const char* text = cbo_fuel_selectcar->text(cbo_fuel_selectcar->value());
		if (text) energy = text;
	}

	float urban = 0.0f;
	float exurban = 0.0f;
	float mixed = 0.0f;
	float co2 = 0.0f;
	if (!get_car_consumption_data(brand, model, gearbox, energy,
	                              urban, exurban, mixed, co2) || mixed <= 0.0f)
	{
		lbl_fuel_usage->value(translate_cstr("N/A"));
		return;
	}

	std::ostringstream out;
	out << std::fixed << std::setprecision(2) << mixed << " L/100 km";
	lbl_fuel_usage->value(out.str().c_str());
}

// Window resizing policy: FLTK's proportional child stretching is disabled,
// then the UI is laid out from a snapshot of the original FLUID geometry.
// Widget boxes and fonts scale with the window. Gaps keep their pixel size from
// 1x upward and shrink below 1x. CARCALC_UI_SCALE overrides the derived factor.
//
// Every widget declared in this .fl file is captured by capture_layout(), so
// new label-only widgets added here scale automatically. Keep manual label
// fixes in this .fl file (as thin Fl_Text_Display/Fl_Output widgets); edits in
// generated C++ would be lost on the next FLUID regeneration.
struct CarCalcGeometry
{
	Fl_Widget* widget;
	int x;
	int y;
	int w;
	int h;
	int nx;
	int ny;
	int nw;
	int nh;
	int index;
	int label_base;
	int label_original;
	int text_base;
	int text_original;
};

struct CarCalcGroupSnapshot
{
	Fl_Widget* container;
	int y;
	std::vector<CarCalcGeometry> children;
};

static Fl_Window* g_scale_window = nullptr;
static int g_base_width = 0;
static int g_base_height = 0;
static double g_font_factor = 1.0;
static double g_applied_factor = 1.0;
static bool g_scale_poll_started = false;
static std::vector<CarCalcGeometry> g_window_snapshots;
static std::vector<CarCalcGroupSnapshot> g_group_snapshots;
static std::map<Fl_Menu_Item*, int> g_menu_font_base;
static std::map<Fl_Menu_Item*, int> g_menu_font_original;

static int scaled_font_size(int size, double factor)
{
	if (size <= 0) return size;
	return std::max(1, static_cast<int>(std::lround(size * factor)));
}

static double clamp_scale(double value)
{
	// No upper cap: a maximized window on a large display must scale all the
	// way to that screen instead of leaving the UI in the top-left corner.
	return std::max(0.5, value);
}

static bool env_scale(double* result)
{
	const char* value = std::getenv("CARCALC_UI_SCALE");
	if (!value || !*value || std::strcmp(value, "auto") == 0) return false;

	char* end = nullptr;
	const double parsed = std::strtod(value, &end);
	if (end == value || *end != '\0' || parsed <= 0.0) return false;

	*result = clamp_scale(parsed);
	return true;
}

static int scale_dim(int value, double factor)
{
	if (value <= 0) return value;
	return std::max(1, static_cast<int>(std::lround(value * factor)));
}

static int scale_offset(int value, double factor)
{
	return static_cast<int>(std::lround(value * factor));
}

// Also used by car_calc_ui.cxx when translations set label sizes, so switching
// language keeps the current window scale instead of resetting the fonts.
int carcalc_scaled_font_size(int size)
{
	if (size <= 0) return size;
	return std::max(1, static_cast<int>(std::lround(size * g_font_factor)));
}

static int widget_text_size(Fl_Widget* widget)
{
	if (Fl_Input_* input = dynamic_cast<Fl_Input_*>(widget)) return input->textsize();
	if (Fl_Browser* browser = dynamic_cast<Fl_Browser*>(widget)) return browser->textsize();
	if (Fl_Text_Display* display = dynamic_cast<Fl_Text_Display*>(widget)) return display->textsize();
	if (Fl_Menu_* menu = dynamic_cast<Fl_Menu_*>(widget)) return menu->textsize();
	return 0;
}

static void set_widget_text_size(Fl_Widget* widget, int size)
{
	if (size <= 0) return;
	if (Fl_Input_* input = dynamic_cast<Fl_Input_*>(widget)) input->textsize(size);
	else if (Fl_Browser* browser = dynamic_cast<Fl_Browser*>(widget)) browser->textsize(size);
	else if (Fl_Text_Display* display = dynamic_cast<Fl_Text_Display*>(widget)) display->textsize(size);
	else if (Fl_Menu_* menu = dynamic_cast<Fl_Menu_*>(widget)) menu->textsize(size);
}

static void capture_menu_fonts(const Fl_Menu_Item* items)
{
	for (const Fl_Menu_Item* item = items; item && item->label(); item = item->next())
	{
		Fl_Menu_Item* editable = const_cast<Fl_Menu_Item*>(item);
		const int size = editable->labelsize();
		if (size > 0 && !g_menu_font_base.count(editable))
		{
			g_menu_font_base[editable] = size;
			g_menu_font_original[editable] = size;
		}
		if (item->flags & FL_SUBMENU) capture_menu_fonts(item + 1);
		else if (item->flags & FL_SUBMENU_POINTER)
			capture_menu_fonts(static_cast<const Fl_Menu_Item*>(item->user_data()));
	}
}

static void apply_menu_fonts(const Fl_Menu_Item* items, double factor)
{
	for (const Fl_Menu_Item* item = items; item && item->label(); item = item->next())
	{
		Fl_Menu_Item* editable = const_cast<Fl_Menu_Item*>(item);
		const auto base = g_menu_font_base.find(editable);
		if (base != g_menu_font_base.end() && base->second > 0)
			editable->labelsize(scaled_font_size(base->second, factor));
		if (item->flags & FL_SUBMENU) apply_menu_fonts(item + 1, factor);
		else if (item->flags & FL_SUBMENU_POINTER)
			apply_menu_fonts(static_cast<const Fl_Menu_Item*>(item->user_data()), factor);
	}
}

static CarCalcGeometry* carcalc_geometry_of(Fl_Widget* widget)
{
	for (CarCalcGeometry& item : g_window_snapshots)
		if (item.widget == widget) return &item;
	for (CarCalcGroupSnapshot& snapshot : g_group_snapshots)
		for (CarCalcGeometry& item : snapshot.children)
			if (item.widget == widget) return &item;
	return nullptr;
}

static void set_widget_font_base(Fl_Widget* widget, int size)
{
	if (!widget) return;
	CarCalcGeometry* item = carcalc_geometry_of(widget);
	if (item) item->label_base = size;
	widget->labelsize(carcalc_scaled_font_size(size));
}

static void set_menu_font_base(Fl_Menu_Item* item, int size)
{
	if (!item) return;
	g_menu_font_base[item] = size;
	item->labelsize(carcalc_scaled_font_size(size));
}

static CarCalcGeometry snapshot_of(Fl_Widget* widget)
{
	const int label = widget->labelsize();
	const int text = widget_text_size(widget);
	return {widget, widget->x(), widget->y(), widget->w(), widget->h(),
	        widget->x(), widget->y(), widget->w(), widget->h(), -1,
	        label, label, text, text};
}

static void freeze_resize(Fl_Group* group)
{
	if (!group) return;
	group->resizable(nullptr);
	for (int i = 0; i < group->children(); ++i)
		freeze_resize(dynamic_cast<Fl_Group*>(group->child(i)));
}

static void capture_layout(Fl_Window* window)
{
	g_window_snapshots.clear();
	g_group_snapshots.clear();

	for (int i = 0; i < window->children(); ++i)
	{
		Fl_Widget* child = window->child(i);
		CarCalcGeometry window_item = snapshot_of(child);
		window_item.index = i;
		g_window_snapshots.push_back(window_item);
		if (Fl_Menu_* menu = dynamic_cast<Fl_Menu_*>(child))
			capture_menu_fonts(menu->menu());

		if (Fl_Group* group = dynamic_cast<Fl_Group*>(child))
		{
			CarCalcGroupSnapshot group_snapshot;
			group_snapshot.container = group;
			group_snapshot.y = child->y();
			for (int j = 0; j < group->children(); ++j)
			{
				CarCalcGeometry child_item = snapshot_of(group->child(j));
				child_item.index = j;
				group_snapshot.children.push_back(child_item);
			}
			g_group_snapshots.push_back(group_snapshot);
		}
	}
}

static void apply_fonts_to_target(double factor)
{
	for (CarCalcGeometry& item : g_window_snapshots)
	{
		item.widget->labelsize(scaled_font_size(item.label_base, factor));
		set_widget_text_size(item.widget, scaled_font_size(item.text_base, factor));
		if (Fl_Menu_* menu = dynamic_cast<Fl_Menu_*>(item.widget))
			apply_menu_fonts(menu->menu(), factor);
	}
	for (CarCalcGroupSnapshot& snapshot : g_group_snapshots)
	{
		for (CarCalcGeometry& item : snapshot.children)
		{
			item.widget->labelsize(scaled_font_size(item.label_base, factor));
			set_widget_text_size(item.widget, scaled_font_size(item.text_base, factor));
		}
	}
}

struct CarCalcRow
{
	int top;
	int bottom;
	std::vector<CarCalcGeometry*> items;
};

static bool is_label_widget(const CarCalcGeometry& item)
{
	const char* label = item.widget->label();
	if (!label || !*label) return false;

	// The original layout uses thin, label-only widgets (Fl_Text_Display and
	// zero-height Fl_Output) instead of real labels. Detect them here so they
	// can follow their value widget instead of being packed as controls.
	if (dynamic_cast<Fl_Text_Display*>(item.widget)) return true;
	if (Fl_Output* output = dynamic_cast<Fl_Output*>(item.widget))
		return (!output->value() || !*output->value()) && item.h <= 2;
	return false;
}

static int measured_label_width(Fl_Widget* widget, int size)
{
	const char* label = widget->label();
	if (!label || !*label) return 0;

	fl_font(widget->labelfont(), size);
	const double width = fl_width(label, static_cast<int>(std::strlen(label)));
	return std::max(1, static_cast<int>(std::lround(width)) + 4);
}

static std::vector<CarCalcRow> build_rows(CarCalcGroupSnapshot& snapshot)
{
	std::vector<CarCalcRow> rows;
	for (CarCalcGeometry& item : snapshot.children)
	{
		if (is_label_widget(item)) continue;

		bool placed = false;
		for (CarCalcRow& row : rows)
		{
			const int overlap = std::min(row.bottom, item.y + item.h) - std::max(row.top, item.y);
			if (overlap > 0)
			{
				row.items.push_back(&item);
				row.top = std::min(row.top, item.y);
				row.bottom = std::max(row.bottom, item.y + item.h);
				placed = true;
				break;
			}
		}
		if (!placed)
			rows.push_back({item.y, item.y + item.h, {&item}});
	}

	for (CarCalcRow& row : rows)
	{
		std::sort(row.items.begin(), row.items.end(),
		          [](const CarCalcGeometry* a, const CarCalcGeometry* b) { return a->x < b->x; });
	}
	std::sort(rows.begin(), rows.end(),
	          [](const CarCalcRow& a, const CarCalcRow& b) { return a.top < b.top; });
	return rows;
}

static int distance_to_rect(const CarCalcGeometry& point, const CarCalcGeometry& rect)
{
	const int cx = point.x + point.w / 2;
	const int cy = point.y + point.h / 2;
	const int dx = std::max(std::max(rect.x - cx, 0), cx - (rect.x + rect.w));
	const int dy = std::max(std::max(rect.y - cy, 0), cy - (rect.y + rect.h));
	return dx + dy;
}

struct CarCalcLabelAnchor
{
	CarCalcGeometry* label;
	CarCalcGeometry* anchor;
	int row;
	int font;
	int required;
	int width;
	int line;
};

struct CarCalcBandCluster
{
	int start;
	int end;
	int band;
	int top;
	int line_height;
};

static int unscaled_font(const CarCalcGeometry& item)
{
	const double current = g_applied_factor > 0.01 ? g_applied_factor : 1.0;
	return std::max(1, static_cast<int>(std::lround(item.widget->labelsize() / current)));
}

static int layout_width(const CarCalcGroupSnapshot& snapshot)
{
	if (g_scale_window && g_scale_window->w() > 0) return g_scale_window->w();
	return snapshot.container ? snapshot.container->w() : 490;
}

static void layout_group(CarCalcGroupSnapshot& snapshot, double factor)
{
	const std::vector<CarCalcRow> rows = build_rows(snapshot);
	if (rows.empty()) return;

	std::vector<int> row_top(rows.size(), 0);
	int next_row_top = scale_offset(rows.front().top, factor);
	for (std::size_t r = 0; r < rows.size(); ++r)
	{
		const CarCalcRow& row = rows[r];
		row_top[r] = next_row_top;
		int bottom = next_row_top;
		int cursor_x = scale_offset(row.items.front()->x, factor);
		for (std::size_t i = 0; i < row.items.size(); ++i)
		{
			CarCalcGeometry& item = *row.items[i];
			item.nw = scale_dim(item.w, factor);
			item.nh = scale_dim(item.h, factor);
			item.nx = cursor_x;
			item.ny = row_top[r] + scale_offset(item.y - row.top, factor);
			bottom = std::max(bottom, item.ny + item.nh);

			int gap = 0;
			if (i + 1 < row.items.size())
			{
				gap = row.items[i + 1]->x - (item.x + item.w);
				// Positive gaps are spacing and stay fixed at 1x and above.
				// Below 1x they shrink with the widgets so small windows still
				// fit. Negative gaps are intentional overlaps and always scale.
				if (gap < 0 || factor < 1.0) gap = scale_offset(gap, factor);
			}
			cursor_x = item.nx + item.nw + gap;
		}

		if (r + 1 < rows.size())
		{
			int gap = rows[r + 1].top - row.bottom;
			if (gap < 0 || factor < 1.0) gap = scale_offset(gap, factor);
			next_row_top = bottom + gap;
		}
	}

	// Label-only widgets are annotations for a nearby value widget. Follow
	// that value's laid-out position, otherwise fixed gaps move the value but
	// not its label and fields such as "Mixed price:" drift out of alignment.
	for (CarCalcGeometry& label : snapshot.children)
	{
		if (!is_label_widget(label)) continue;
		label.nw = scale_dim(label.w, factor);
		label.nh = scale_dim(label.h, factor);

		CarCalcGeometry* anchor = nullptr;
		int best_score = 1000000000;
		const char* text = label.widget->label();
		if (text && std::strchr(text, ':'))
		{
			for (CarCalcGeometry& candidate : snapshot.children)
			{
				if (is_label_widget(candidate) || candidate.h <= 0) continue;
				// Only result displays are valid anchors; buttons and inputs
				// can share a row with a label but must not move it.
				if (!dynamic_cast<Fl_Output*>(candidate.widget) &&
				    !dynamic_cast<Fl_Text_Display*>(candidate.widget)) continue;
				if (candidate.widget->label() && *candidate.widget->label()) continue;
				const int dx = candidate.x - label.x;
				const int dy = candidate.y - label.y;
				if (dy < -32 || dy > 8) continue;
				if (dx < -label.w / 2) continue;
				// Value boxes normally start just past the label's right edge
				// and sit 20 pixels above its baseline.
				const int score = std::abs(dx - label.w) + std::abs(dy + 20) * 3;
				if (score < best_score)
				{
					best_score = score;
					anchor = &candidate;
				}
			}
		}

		if (anchor)
		{
			label.nx = anchor->nx + scale_offset(label.x - anchor->x, factor);
			label.ny = anchor->ny + scale_offset(label.y - anchor->y, factor);
		}
		else
		{
			label.nx = scale_offset(label.x, factor);
			label.ny = scale_offset(label.y, factor);
		}
	}
}

struct CarCalcLayoutSize
{
	int width;
	int height;
};

static CarCalcLayoutSize layout_size(Fl_Window* window, double factor)
{
	CarCalcLayoutSize size = {0, 0};
	for (const CarCalcGeometry& item : g_window_snapshots)
	{
		size.width = std::max(size.width, scale_offset(item.x, factor) + scale_dim(item.w, factor));
		size.height = std::max(size.height, scale_offset(item.y, factor) + scale_dim(item.h, factor));
	}
	for (CarCalcGroupSnapshot& snapshot : g_group_snapshots)
	{
		CarCalcGroupSnapshot trial = snapshot;
		layout_group(trial, factor);
		for (const CarCalcGeometry& item : trial.children)
		{
			size.width = std::max(size.width, item.nx + item.nw);
			size.height = std::max(size.height,
			                       scale_offset(snapshot.y, factor) + item.ny + item.nh);
		}
	}
	(void)window;
	return size;
}

static void apply_layout(Fl_Window* window, double factor);

static CarCalcLayoutSize actual_layout_size(Fl_Window* window, double factor)
{
	apply_layout(window, factor);
	CarCalcLayoutSize size = {0, 0};
	for (const CarCalcGeometry& item : g_window_snapshots)
	{
		size.width = std::max(size.width, item.widget->x() + item.widget->w());
		size.height = std::max(size.height, item.widget->y() + item.widget->h());
	}
	for (const CarCalcGroupSnapshot& snapshot : g_group_snapshots)
	{
		for (const CarCalcGeometry& item : snapshot.children)
		{
			size.width = std::max(size.width, item.widget->x() + item.widget->w());
			size.height = std::max(size.height,
			                       snapshot.container->y() + item.widget->y() + item.widget->h());
		}
	}
	return size;
}

static bool layout_fits(Fl_Window* window, double factor)
{
	const CarCalcLayoutSize size = layout_size(window, factor);
	return size.width <= window->w() && size.height <= window->h();
}

static double fitted_scale(Fl_Window* window, double factor)
{
	if (!window || g_group_snapshots.empty()) return factor;
	if (layout_fits(window, factor)) return factor;

	const double minimum = clamp_scale(0.5);
	double low = minimum;
	double high = factor;
	if (!layout_fits(window, low)) return low;

	// Find the largest factor that still fits, instead of stepping down from
	// the requested factor and stopping early.
	for (int i = 0; i < 24; ++i)
	{
		const double mid = (low + high) / 2.0;
		if (layout_fits(window, mid)) low = mid;
		else high = mid;
	}
	return low;
}

struct CarCalcTextRun
{
	int x;
	int y;
	int w;
	int h;
};

static std::vector<CarCalcTextRun>* g_text_runs = nullptr;

// FLTK positions and wraps label text inside a widget box. Use its own draw
// callback to measure the resulting runs instead of guessing from fl_width().
static void carcalc_measure_run(const char* text, int length, int x, int y)
{
	if (!g_text_runs) return;
	int dx = 0;
	int dy = 0;
	int w = 0;
	int h = 0;
	fl_text_extents(text, length, dx, dy, w, h);
	if (w > 0 && h > 0)
		g_text_runs->push_back({x + dx, y + dy, w, h});
}

static std::vector<CarCalcTextRun> carcalc_label_runs(const CarCalcGeometry& item)
{
	std::vector<CarCalcTextRun> runs;
	const char* text = item.widget->label();
	if (!text || !*text) return runs;

	const Fl_Boxtype box = item.widget->box();
	int x = item.nx + Fl::box_dx(box);
	int y = item.ny + Fl::box_dy(box);
	int w = item.nw - Fl::box_dw(box);
	int h = item.nh - Fl::box_dh(box);

	const Fl_Align align = item.widget->align();
	if (w > 11 && (align & (FL_ALIGN_LEFT | FL_ALIGN_RIGHT)))
	{
		x += 3;
		w -= 6;
	}

	fl_font(item.widget->labelfont(), item.widget->labelsize());
	g_text_runs = &runs;
	fl_draw(text, x, y, w, h, align, carcalc_measure_run, nullptr, 0);
	g_text_runs = nullptr;
	return runs;
}

static bool carcalc_runs_overlap(const CarCalcTextRun& a, const CarCalcTextRun& b)
{
	const int dx = std::min(a.x + a.w, b.x + b.w) - std::max(a.x, b.x);
	const int dy = std::min(a.y + a.h, b.y + b.h) - std::max(a.y, b.y);
	return dx > 1 && dy > 1;
}

static bool carcalc_runs_collide(const std::vector<CarCalcTextRun>& runs,
                                 const CarCalcGeometry& item,
                                 const std::vector<CarCalcGeometry>& children)
{
	for (const CarCalcGeometry& other : children)
	{
		if (other.widget == item.widget || is_label_widget(other)) continue;
		const CarCalcTextRun box = {other.nx, other.ny, other.nw, other.nh};
		for (const CarCalcTextRun& run : runs)
			if (carcalc_runs_overlap(run, box)) return true;
	}
	for (const CarCalcGeometry& other : children)
	{
		if (other.widget == item.widget || !other.widget->label() || !*other.widget->label())
			continue;
		const std::vector<CarCalcTextRun> other_runs = carcalc_label_runs(other);
		for (const CarCalcTextRun& run : runs)
			for (const CarCalcTextRun& other_run : other_runs)
				if (carcalc_runs_overlap(run, other_run)) return true;
	}
	return false;
}

// Labels can still collide after scaling because translations are longer than
// English and because the original layout uses zero-height label widgets.
// Move label-only annotations first, then shrink only the colliding text until
// the measured runs no longer cover anything else.
static void carcalc_resolve_text(CarCalcGroupSnapshot& snapshot, double factor)
{
	// Several passes let one widget's shrink make room for a neighbouring
	// label that was processed earlier in the same pass.
	for (int pass = 0; pass < 4; ++pass)
	{
		bool changed = false;
		for (CarCalcGeometry& item : snapshot.children)
		{
			if (!item.widget->label() || !*item.widget->label()) continue;

			std::vector<CarCalcTextRun> runs = carcalc_label_runs(item);
			int guard = 0;
			while (carcalc_runs_collide(runs, item, snapshot.children) && guard++ < 160)
			{
				bool moved = false;
				if (is_label_widget(item))
				{
					// Search in laid-out pixels: row spacing grows with the
					// window, so a fixed 160px search cannot escape a scaled
					// value box at large sizes.
					const int move_limit = std::max(160, scaled_font_size(160, factor));
					for (int distance = 1; distance <= move_limit && !moved; ++distance)
					{
						const int deltas[2] = {-distance, distance};
						for (int delta : deltas)
						{
							const int original_y = item.ny;
							item.ny += delta;
							const std::vector<CarCalcTextRun> trial = carcalc_label_runs(item);
							bool inside = true;
							if (g_scale_window)
							{
								const int group_y = snapshot.container ? snapshot.container->y() : 0;
								const int absolute_y = group_y + item.ny;
								if (absolute_y < 0 || absolute_y + item.nh > g_scale_window->h())
									inside = false;
								for (const CarCalcTextRun& run : trial)
									if (run.y < 0 || run.y + run.h > g_scale_window->h())
										inside = false;
							}
							if (inside && !carcalc_runs_collide(trial, item, snapshot.children))
							{
								runs = trial;
								moved = true;
								break;
							}
							item.ny = original_y;
						}
					}
				}
				if (moved) continue;

				const int size = item.widget->labelsize();
				const int minimum = scaled_font_size(4, factor);
				if (size > minimum)
				{
					item.widget->labelsize(size - 1);
					runs = carcalc_label_runs(item);
					changed = true;
					continue;
				}
				break;
			}
		}
		if (!changed) break;
	}
}

static void apply_layout(Fl_Window* window, double factor)
{
	// Font sizes are derived from captured (or translated) base sizes on every
	// pass, so collision-driven shrink adjustments never accumulate across
	// resizes or language changes.
	apply_fonts_to_target(factor);

	for (CarCalcGeometry& item : g_window_snapshots)
	{
		const int y = scale_offset(item.y, factor);
		const int h = dynamic_cast<Fl_Group*>(item.widget)
		            ? std::max(1, window->h() - y) : scale_dim(item.h, factor);
		item.widget->resize(0, y, window->w(), h);
		item.nx = 0;
		item.ny = y;
		item.nw = window->w();
		item.nh = h;
	}

	for (CarCalcGroupSnapshot& snapshot : g_group_snapshots)
	{
		layout_group(snapshot, factor);
		carcalc_resolve_text(snapshot, factor);
		for (CarCalcGeometry& item : snapshot.children)
			item.widget->resize(item.nx, item.ny, item.nw, item.nh);
	}
}

static bool layout_drifted()
{
	for (const CarCalcGeometry& item : g_window_snapshots)
	{
		if (item.widget->x() != item.nx || item.widget->y() != item.ny ||
		    item.widget->w() != item.nw || item.widget->h() != item.nh)
			return true;
	}
	for (const CarCalcGroupSnapshot& snapshot : g_group_snapshots)
	{
		for (const CarCalcGeometry& item : snapshot.children)
		{
			if (item.widget->x() != item.nx || item.widget->y() != item.ny ||
			    item.widget->w() != item.nw || item.widget->h() != item.nh)
				return true;
		}
	}
	return false;
}

static double desired_font_scale(Fl_Window* window)
{
	if (!window) return 1.0;

	// An explicit override stays fixed, as before. Automatic scaling is only
	// reduced when the resized layout would otherwise overflow the window.
	double fixed = 1.0;
	if (env_scale(&fixed)) return fixed;

	if (g_base_width <= 0 || g_base_height <= 0) return 1.0;
	const double candidate = std::min(static_cast<double>(window->w()) / g_base_width,
	                                  static_cast<double>(window->h()) / g_base_height);
	return fitted_scale(window, clamp_scale(candidate));
}

static void refresh_scale()
{
	Fl_Window* window = g_scale_window;
	if (!window) return;

	const double target = desired_font_scale(window);
	// FLTK stretches the window's children whenever the window is resized,
	// even if the derived scale factor stays the same. Reapply the snapshot
	// layout in that case so the flat layout is restored immediately.
	if (!layout_drifted() && std::fabs(target - g_applied_factor) < 0.001) return;

	g_font_factor = target;
	apply_layout(window, target);
	g_applied_factor = target;
	window->redraw();
}

// Used after a language change, when .trs font sizes are applied.
void carcalc_relayout()
{
	if (!g_scale_window) return;
	apply_layout(g_scale_window, g_font_factor);
	g_scale_window->redraw();
}

static void poll_scale(void*)
{
	refresh_scale();
	Fl::repeat_timeout(0.05, poll_scale);
}

void apply_font_scale(Fl_Window* window)
{
	if (!window) return;

	g_scale_window = window;
	g_font_factor = 1.0;
	g_applied_factor = 1.0;

	capture_layout(window);

	// Keep the original FLUID window size unless the scaled flat layout needs
	// more room.
	const CarCalcLayoutSize needed = layout_size(window, 1.0);
	const int initial_width = std::min(std::max(window->w(), needed.width), Fl::w());
	const int initial_height = std::min(std::max(window->h(), needed.height), Fl::h());
	if (initial_width != window->w() || initial_height != window->h())
		window->size(initial_width, initial_height);
	g_base_width = window->w();
	g_base_height = window->h();

	// Find the smallest factor whose layout still fits at the matching window
	// size, then let the WM resize freely from there up to the whole screen.
	double smallest_factor = 1.0;
	for (int step = 20; step >= 10; --step)
	{
		const double candidate = step / 20.0;
		const CarCalcLayoutSize candidate_size = actual_layout_size(window, candidate);
		if (candidate_size.width <= scale_dim(g_base_width, candidate) &&
		    candidate_size.height <= scale_dim(g_base_height, candidate))
			smallest_factor = candidate;
		else
			break;
	}
	const int min_width = scale_dim(g_base_width, smallest_factor);
	const int min_height = scale_dim(g_base_height, smallest_factor);
	if (Fl::w() > 0 && Fl::h() > 0)
		window->size_range(min_width, min_height, Fl::w(), Fl::h());
	else
		window->size_range(min_width, min_height);

	// Keep the window itself resizable by the window manager. Only the nested
	// groups are frozen so FLTK cannot stretch their children; refresh_scale()
	// relayouts them from the snapshot after each resize.
	for (int i = 0; i < window->children(); ++i)
		freeze_resize(dynamic_cast<Fl_Group*>(window->child(i)));

	// The initial factor is 1, so refresh_scale() would otherwise consider it
	// unchanged and skip the first flat-layout pass.
	apply_layout(window, 1.0);
	refresh_scale();

	if (!g_scale_poll_started)
	{
		Fl::add_timeout(0.05, poll_scale);
		g_scale_poll_started = true;
	}
}

static std::string ui_to_lower(std::string s)
{
  std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
  return s;
}

static int ui_match_score(const std::string &text, const std::string &query)
{
  if (query.empty()) return 0;
  std::string t = ui_to_lower(text);
  std::string q = ui_to_lower(query);
  if (t == q) return 100000;
  if (t.size() >= q.size() && t.compare(0, q.size(), q) == 0) return 90000 - static_cast<int>(t.size() - q.size());
  size_t pos = t.find(q);
  if (pos != std::string::npos) return 80000 - static_cast<int>(pos) * 100 - static_cast<int>(t.size() - q.size());

  // subsequence (fuzzy) match
  size_t ti = 0, qi = 0, first = std::string::npos, last = 0;
  while (ti < t.size() && qi < q.size())
  {
    if (t[ti] == q[qi])
    {
      if (first == std::string::npos) first = ti;
      last = ti;
      ++qi;
    }
    ++ti;
  }
  if (qi == q.size() && first != std::string::npos)
  {
    int span = static_cast<int>(last - first + 1);
    int gaps = span - static_cast<int>(q.size());
    return 70000 - span * 50 - gaps * 10 - static_cast<int>(first);
  }

  return 0;
}

static bool ui_match_better(const std::string &a, const std::string &b, const std::string &query)
{
  int sa = ui_match_score(a, query);
  int sb = ui_match_score(b, query);
  if (sa != sb) return sa > sb;
  std::string la = ui_to_lower(a);
  std::string lb = ui_to_lower(b);
  if (la != lb) return la < lb;
  return a < b;
}

static void replace_all_text(std::string &text, const std::string &from, const std::string &to)
{
  if (from.empty()) return;
  size_t pos = 0;
  while ((pos = text.find(from, pos)) != std::string::npos)
  {
    text.replace(pos, from.size(), to);
    pos += to.size();
  }
}

static std::string localize_price_text(std::string text)
{
  const std::string key = canonical_text(text);
  if (key == "N/A" || key == "N/D")
  {
    const char *translated = translate_cstr("N/A");
    return translated ? std::string(translated) : text;
  }
  const char *unit = translate_cstr("PLN/l");
  replace_all_text(text, "PLN/l", unit ? unit : "PLN/l");
  replace_all_text(text, "zł/l", unit ? unit : "PLN/l");
  return text;
}

static void translate_widget(Fl_Widget *widget)
{
  if (!widget) return;
  const char *label = widget->label();
  const std::string key = canonical_text(label ? label : "");
  const char *translated = translate_cstr(key.c_str());
  if (translated && (!label || std::strcmp(label, translated) != 0))
    widget->copy_label(translated);
  const int size = translation_size(key.c_str());
  CarCalcGeometry* geometry = carcalc_geometry_of(widget);
  if (size > 0) set_widget_font_base(widget, size);
  else if (geometry) set_widget_font_base(widget, geometry->label_original);

  Fl_Output *output = dynamic_cast<Fl_Output *>(widget);
  if (output && output->value())
  {
    const std::string localized = localize_price_text(output->value());
    if (localized != output->value()) output->value(localized.c_str());
  }
}

static void translate_menu_item(Fl_Menu_Item *item, const char *english)
{
  if (!item) return;
  item->label(translate_cstr(english));
  const int size = translation_size(english);
  const auto original = g_menu_font_original.find(item);
  if (size > 0) set_menu_font_base(item, size);
  else if (original != g_menu_font_original.end()) set_menu_font_base(item, original->second);
}

static void translate_widget_group(Fl_Group *group)
{
  if (!group) return;
  for (int i = 0; i < group->children(); ++i)
    translate_widget(group->child(i));
}

